export default "/* content.css — domain residue for com.ikenga.content.\n *\n * Only content-local classes live here:\n *   - .ct-* Calendar view layout (.ct-cal-grid, .ct-cal-pill, .ct-cal-legend)\n *   - .ct-* Published view layout (.ct-pub-kpis, .ct-pub-kpi, .ct-mv-badge, .ct-pub-table)\n *   - .pl-* Pipeline list split layout (domain-local split chrome)\n *   - Kanban stage dot colours for content stages\n *   - Reduced-motion overrides for content-specific transitions\n *\n * Kit primitives (.frame*, .ip-split*, .dense-row*, .btn*, .tag, .chip, .badge,\n * .atelier-state*, .nav-group*, .nav-item*, .kb-*, .seg*, .split-*, etc.) are\n * consumed from app-kit-css.js — never re-derived here.\n *\n * Inject order: tokens-css → app-kit-css → content-css (this file).\n * data-workspace=\"studio\" on <html> → warm terracotta-red tint for active nav + accents.\n */\n\n/* ── Reduced motion gate ── */\n@media (prefers-reduced-motion: reduce) {\n  .split-row { transition: none; }\n  .kb-card { transition: none; }\n  .kb-card:hover { transform: none; }\n  .pl-row { transition: none; }\n}\n\n/* ── Kanban stage dot colours (content stages) ─────────────────────────────── */\n/* Idea: fg-faint · Outline: systemic · Draft: primary · Review: achievement · Scheduled: live */\n\n.kb-col[data-stage=\"idea\"] .kb-col-dot       { background: var(--fg-faint, rgba(128,128,128,0.4)); }\n.kb-col[data-stage=\"outline\"] .kb-col-dot    { background: var(--systemic, hsl(140,55%,42%)); }\n.kb-col[data-stage=\"draft\"] .kb-col-dot      { background: var(--primary, hsl(215,70%,55%)); }\n.kb-col[data-stage=\"review\"] .kb-col-dot     { background: var(--achievement, hsl(38,85%,52%)); }\n.kb-col[data-stage=\"scheduled\"] .kb-col-dot  { background: var(--live, hsl(348,72%,52%)); }\n\n/* Tolerant extras: any non-enum stage gets a neutral dot */\n.kb-col:not([data-stage=\"idea\"]):not([data-stage=\"outline\"]):not([data-stage=\"draft\"]):not([data-stage=\"review\"]):not([data-stage=\"scheduled\"]) .kb-col-dot {\n  background: var(--fg-faint, rgba(128,128,128,0.3));\n}\n\n/* Kanban board horizontal scroll mask */\n.kb-board-wrap {\n  overflow-x: auto;\n  height: 100%;\n  -webkit-mask-image: linear-gradient(to right, black calc(100% - 40px), transparent 100%);\n  mask-image: linear-gradient(to right, black calc(100% - 40px), transparent 100%);\n}\n\n/* ── UX-mode dots (content domain) ─────────────────────────────────────────── */\n\n.ux-dot {\n  display: inline-block;\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n  flex-shrink: 0;\n  margin-right: 4px;\n}\n.ux-dot.ux-confirm  { background: var(--achievement, hsl(38,85%,52%)); }\n.ux-dot.ux-silent   { background: var(--fg-faint, rgba(128,128,128,0.4)); }\n.ux-dot.ux-approve  { background: var(--primary, hsl(215,70%,55%)); }\n\n/* ── Next-action chip in list rows ───────────────────────────────────────────── */\n\n.next-chip {\n  display: inline-flex;\n  align-items: center;\n  gap: 3px;\n  font-size: 0.68rem;\n  color: var(--fg-muted);\n  background: var(--bg-inset, rgba(0,0,0,0.06));\n  border-radius: 4px;\n  padding: 2px 6px;\n  max-width: 180px;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n/* ── Stage chip in detail pane ─────────────────────────────────────────────── */\n\n.stage-chip {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  font-size: 0.7rem;\n  font-weight: 600;\n  padding: 3px 8px;\n  border-radius: 5px;\n  background: var(--bg-inset, rgba(0,0,0,0.07));\n  color: var(--fg-muted);\n  text-transform: capitalize;\n  letter-spacing: 0.03em;\n}\n\n/* ── Hot filter (Due this week — achievement tint) ──────────────────────────── */\n\n.nav-item.is-hot .nav-item-count {\n  color: var(--achievement, hsl(38,85%,52%));\n  font-weight: 700;\n}\n\n/* ── Pipeline list (.pl-*) ──────────────────────────────────────────────────── */\n\n/* Amount in list rows */\n.pl-row-amt {\n  font-family: var(--font-mono, monospace);\n  font-size: 0.78rem;\n  font-weight: 600;\n  color: var(--fg);\n  white-space: nowrap;\n}\n\n/* Due date display */\n.pl-row-due {\n  font-size: 0.68rem;\n  color: var(--fg-faint, var(--fg-muted));\n  font-family: var(--font-mono, monospace);\n  white-space: nowrap;\n}\n\n.pl-row-due.is-urgent {\n  color: var(--danger, hsl(0,65%,52%));\n}\n\n/* Split-detail facts grid */\n.split-facts {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 8px 16px;\n  margin: 12px 0;\n}\n\n.split-fact-k {\n  font-size: 0.68rem;\n  color: var(--fg-muted);\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n  font-weight: 600;\n}\n\n.split-fact-v {\n  font-size: 0.82rem;\n  color: var(--fg);\n  font-weight: 500;\n}\n\n/* Next-action card in split-detail */\n.split-next {\n  border: 1px solid var(--border-soft, rgba(0,0,0,0.08));\n  border-radius: 7px;\n  overflow: hidden;\n  margin: 12px 0;\n}\n\n.split-next-head {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  padding: 8px 12px;\n  font-size: 0.72rem;\n  font-weight: 600;\n  color: var(--fg-muted);\n  background: var(--bg-inset, rgba(0,0,0,0.04));\n  border-bottom: 1px solid var(--border-soft, rgba(0,0,0,0.06));\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n}\n\n.split-next-body {\n  padding: 10px 12px;\n  font-size: 0.82rem;\n  color: var(--fg);\n  line-height: 1.4;\n}\n\n/* Activity timeline in detail pane */\n.split-timeline {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  margin-top: 12px;\n}\n\n.split-tl-row {\n  display: flex;\n  gap: 10px;\n  align-items: flex-start;\n}\n\n.split-tl-dot {\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n  background: var(--fg-faint, rgba(128,128,128,0.4));\n  flex-shrink: 0;\n  margin-top: 5px;\n}\n\n.split-tl-body {\n  flex: 1;\n}\n\n.split-tl-title {\n  font-size: 0.78rem;\n  color: var(--fg);\n}\n\n.split-tl-when {\n  font-size: 0.65rem;\n  color: var(--fg-faint, var(--fg-muted));\n  font-family: var(--font-mono, monospace);\n}\n\n/* Seg toggle (list/kanban) injected into sidebar nav-group */\n.nav-view-seg {\n  margin: 4px 8px 6px;\n}\n\n/* ── Calendar view (.ct-cal-*) ─────────────────────────────────────────────── */\n\n.ct-mv-wrap {\n  overflow-y: auto;\n  padding: 16px;\n  height: 100%;\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n}\n\n.ct-cal-section-title {\n  font-size: 0.72rem;\n  font-weight: 600;\n  color: var(--fg-muted);\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n  margin-bottom: 8px;\n}\n\n.ct-cal-grid {\n  display: grid;\n  grid-template-columns: repeat(7, 1fr);\n  gap: 6px;\n  background: var(--bg-surface, var(--bg-base));\n  border: 1px solid var(--border-soft, rgba(0,0,0,0.08));\n  border-radius: 8px;\n  padding: 10px;\n}\n\n.ct-cal-dow {\n  font-size: 0.62rem;\n  font-weight: 600;\n  color: var(--fg-muted);\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n  padding: 2px 6px;\n  text-align: center;\n}\n\n.ct-cal-day {\n  min-height: 56px;\n  border-radius: 5px;\n  padding: 4px 6px;\n  background: var(--bg-inset, rgba(0,0,0,0.03));\n  display: flex;\n  flex-direction: column;\n  gap: 3px;\n  transition: background 0.1s;\n}\n\n.ct-cal-day.dim {\n  opacity: 0.45;\n}\n\n.ct-cal-date {\n  font-size: 0.65rem;\n  font-family: var(--font-mono, monospace);\n  color: var(--fg-faint, var(--fg-muted));\n  margin-bottom: 2px;\n}\n\n/* Channel-coloured calendar pills — DOMAIN LOCAL.\n * Note: badge-tag-chip also defines a .cal-pill class with different semantics\n * (outbound schedule slots). Use .ct-cal-pill to avoid collision. */\n.ct-cal-pill {\n  display: block;\n  font-size: 0.62rem;\n  padding: 2px 5px;\n  border-radius: 3px;\n  color: #fff;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  font-weight: 500;\n  line-height: 1.3;\n}\n\n/* Channel colour assignments (fixed semantic — not user-configurable in v1) */\n.ct-cal-pill[data-channel=\"blog\"]         { background: var(--primary, hsl(215,70%,55%)); }\n.ct-cal-pill[data-channel=\"newsletter\"]   { background: var(--achievement, hsl(38,85%,52%)); }\n.ct-cal-pill[data-channel=\"social\"]       { background: var(--systemic, hsl(140,55%,42%)); }\n.ct-cal-pill[data-channel=\"video\"]        { background: var(--agent, hsl(265,55%,58%)); }\n/* Fallback for unknown channels */\n.ct-cal-pill                              { background: var(--fg-faint, rgba(128,128,128,0.5)); }\n\n.ct-cal-legend {\n  display: flex;\n  gap: 14px;\n  align-items: center;\n  flex-wrap: wrap;\n  padding: 8px 0 2px;\n}\n\n.ct-cal-legend-item {\n  display: flex;\n  align-items: center;\n  gap: 5px;\n  font-size: 0.68rem;\n  color: var(--fg-muted);\n}\n\n.ct-cal-legend-dot {\n  width: 8px;\n  height: 8px;\n  border-radius: 2px;\n  flex-shrink: 0;\n}\n\n.ct-cal-legend-dot[data-channel=\"blog\"]       { background: var(--primary, hsl(215,70%,55%)); }\n.ct-cal-legend-dot[data-channel=\"newsletter\"] { background: var(--achievement, hsl(38,85%,52%)); }\n.ct-cal-legend-dot[data-channel=\"social\"]     { background: var(--systemic, hsl(140,55%,42%)); }\n.ct-cal-legend-dot[data-channel=\"video\"]      { background: var(--agent, hsl(265,55%,58%)); }\n\n/* ── Published view (.ct-pub-*) ─────────────────────────────────────────────── */\n\n.ct-pub-wrap {\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n  padding: 16px;\n  overflow-y: auto;\n  height: 100%;\n}\n\n.ct-pub-kpis {\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  gap: 10px;\n}\n\n.ct-pub-kpi {\n  background: var(--bg-surface, var(--bg-base));\n  border: 1px solid var(--border-soft, rgba(0,0,0,0.08));\n  border-radius: 8px;\n  padding: 14px 16px;\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n\n.ct-kpi-k {\n  font-size: 0.72rem;\n  font-weight: 500;\n  color: var(--fg-muted);\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n}\n\n.ct-kpi-v {\n  font-size: 1.35rem;\n  font-weight: 700;\n  color: var(--fg);\n  font-family: var(--font-mono, monospace);\n}\n\n.ct-kpi-sub {\n  font-size: 0.7rem;\n  color: var(--fg-faint, var(--fg-muted));\n  font-family: var(--font-mono, monospace);\n}\n\n.ct-pub-card {\n  background: var(--bg-surface, var(--bg-base));\n  border: 1px solid var(--border-soft, rgba(0,0,0,0.08));\n  border-radius: 8px;\n  overflow: hidden;\n}\n\n.ct-pub-card-h {\n  padding: 10px 14px;\n  font-size: 0.8rem;\n  font-weight: 600;\n  color: var(--fg-muted);\n  border-bottom: 1px solid var(--border-soft, rgba(0,0,0,0.06));\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n}\n\n/* Published view table */\n.ct-pub-table {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: 0.8rem;\n}\n\n.ct-pub-table thead tr {\n  background: var(--bg-inset, rgba(0,0,0,0.04));\n}\n\n.ct-pub-table th {\n  padding: 8px 12px;\n  text-align: left;\n  font-size: 0.7rem;\n  font-weight: 600;\n  color: var(--fg-muted);\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n  border-bottom: 1px solid var(--border-soft, rgba(0,0,0,0.08));\n}\n\n.ct-pub-table td {\n  padding: 9px 12px;\n  border-bottom: 1px solid var(--border-soft, rgba(0,0,0,0.04));\n  color: var(--fg);\n  vertical-align: middle;\n}\n\n.ct-pub-table tbody tr:last-child td {\n  border-bottom: none;\n}\n\n.ct-pub-table tbody tr:hover td {\n  background: var(--bg-hover, rgba(0,0,0,0.025));\n}\n\n/* Channel badge in published table */\n.ct-mv-badge {\n  display: inline-flex;\n  align-items: center;\n  padding: 2px 7px;\n  border-radius: 4px;\n  font-size: 0.65rem;\n  font-weight: 500;\n  text-transform: capitalize;\n  letter-spacing: 0.02em;\n}\n\n.ct-mv-badge[data-channel=\"blog\"]       { background: color-mix(in srgb, var(--primary, hsl(215,70%,55%)) 18%, transparent); color: var(--primary, hsl(215,70%,55%)); }\n.ct-mv-badge[data-channel=\"newsletter\"] { background: color-mix(in srgb, var(--achievement, hsl(38,85%,52%)) 18%, transparent); color: var(--achievement, hsl(38,85%,52%)); }\n.ct-mv-badge[data-channel=\"social\"]     { background: color-mix(in srgb, var(--systemic, hsl(140,55%,42%)) 18%, transparent); color: var(--systemic, hsl(140,55%,42%)); }\n.ct-mv-badge[data-channel=\"video\"]      { background: color-mix(in srgb, var(--agent, hsl(265,55%,58%)) 18%, transparent); color: var(--agent, hsl(265,55%,58%)); }\n.ct-mv-badge {\n  background: var(--bg-inset, rgba(0,0,0,0.08));\n  color: var(--fg-muted);\n}\n\n/* Views count in published table */\n.ct-pub-views {\n  font-family: var(--font-mono, monospace);\n  font-size: 0.78rem;\n  font-weight: 600;\n  color: var(--fg);\n}\n\n/* Engagement percent in published table */\n.ct-pub-eng {\n  font-family: var(--font-mono, monospace);\n  font-size: 0.75rem;\n  color: var(--systemic, hsl(140,55%,42%));\n  font-weight: 500;\n}\n"
